import {captureView} from './navigation-27ca4e179461.mjs';
import * as D from './domain-27ca4e179461.mjs';
import {saveIterationNode,saveIterationEntry,iterationPath,ITERATION_FIELDS,iterationNumber,iterationArchived} from './rebuild-model-27ca4e179461.mjs';
import {e} from './views-27ca4e179461.mjs';
export function createIterationUI({getState,getUI,tasks,save,render,navigate,openModal,entityReplace}){
 async function editNode(id=null,{resume=null,onReturn=null}={}){const s=getState(),ui=getUI(),old=s.iterationNodes.find(n=>n.id===id),node=old??{id:D.uid(),title:'',branch:ui.iterationBranch??'time',parentId:ui.iterationParent??null,kind:'project',archived:false,createdAt:Date.now()};await tasks.open({id:resume?.id??('iteration-node:'+(id??node.branch+':'+(node.parentId??'root'))),kind:'iteration-node',onReturn,title:old?'项目设置':'新建项目',original:old,initial:{...node,archived:node.archived?['on']:[]},extra:{entityId:node.id},body:()=>`<label>名称<input name="title" maxlength="100" required autofocus></label><label>放在哪里<select name="parentId"><option value="">日常通用 / 本分支</option>${s.iterationNodes.filter(n=>n.branch===node.branch&&n.id!==id).map(n=>`<option value="${e(n.id)}">${e(iterationPath(s,n.id))}</option>`).join('')}</select></label><details><summary>分类与归档</summary><label>用途<select name="kind"><option value="project">项目，可以直接记录</option><option value="category">分类，也可以直接记录</option></select></label><label class="check"><input type="checkbox" name="archived">归档收起</label></details>`,onSave:async(f,{commit,original,payload})=>{await commit(s=>{if(original&&JSON.stringify(s.iterationNodes.find(n=>n.id===id))!==JSON.stringify(original))throw Error('项目已变化，请核对后保存');return saveIterationNode(s,{...node,id:payload.entityId,title:f.get('title'),parentId:f.get('parentId'),kind:f.get('kind'),archived:f.has('archived')});});},onSaved:onReturn??(payload=>navigate('iteration',{navPage:'iteration',iterationParent:payload.entityId,iterationBranch:node.branch,iterationQuery:'',iterationDate:''}))});}
 async function editEntry(nodeId,id=null){const origin=captureView(getUI()),s=getState(),old=s.iterationEntries.find(v=>v.id===id),n=s.iterationNodes.find(n=>n.id===(old?.nodeId??nodeId));if(!n)throw Error('项目不存在');if(iterationArchived(s,n)&&!old)throw Error('先恢复这个项目，再记录新内容');const initial={...old,at:D.localInput(old?.at??Date.now(),s.timeZone,true),reference:old?.reference?['on']:[]};await tasks.open({id:'iteration-entry:'+(id??'new:'+n.id),kind:'iteration-entry',title:n.title+' · 记一次',original:old,initial,extra:{entityId:old?.id??D.uid()},body:()=>`<p class="r-date">${e(iterationPath(s,n.id))} · ${old?'第 '+iterationNumber(s,old)+' 次':'新记录'}</p><label>日期<input name="at" type="datetime-local" step="1" required></label>${ITERATION_FIELDS.map(([key,title])=>`<label>${title}<textarea name="${key}" maxlength="10000" rows="2" placeholder="可跳过"></textarea></label>`).join('')}<details><summary>个人参考与方法心得</summary><label class="check"><input name="reference" type="checkbox">标为个人参考</label><label>方法心得<textarea name="method" maxlength="10000"></textarea></label></details>`,onSave:async(f,{commit,original,payload})=>{const values=Object.fromEntries(ITERATION_FIELDS.map(([k])=>[k,String(f.get(k)??'')]));await commit(s=>{if(original&&JSON.stringify(s.iterationEntries.find(v=>v.id===id))!==JSON.stringify(original))throw Error('这条记录已变化，填写保留');return saveIterationEntry(s,{...values,id:payload.entityId,nodeId:n.id,at:D.parseLocal(f.get('at'),s.timeZone),reference:f.has('reference'),method:f.get('method')});});},onSaved:()=>{if(origin.page==='iteration'){Object.assign(getUI(),origin);render();}else return navigate('iteration',{navPage:'iteration',iterationParent:n.id,iterationBranch:n.branch,iterationQuery:'',iterationDate:''});}});}
 function compare(ids){
  const s=getState(),rows=ids.map(id=>s.iterationEntries.find(v=>v.id===id));
  if(rows.length<2||rows.length>4||new Set(rows.map(r=>r?.nodeId)).size!==1||rows.some(r=>!r))throw Error('请选择同一项目的2—4次记录');
  let selected=[rows[0].id,rows[1].id];
  const caption=r=>D.dateKey(r.at,s.timeZone)+' · 第 '+iterationNumber(s,r)+' 次'+(r.reference?' · 个人参考':'');
  function draw(){const pair=selected.map(id=>rows.find(r=>r.id===id));
   openModal('并排回看',`<div class="r-compare"><div class="r-compare-head">${pair.map((r,i)=>`<div><strong>${D.dateKey(r.at,s.timeZone)}</strong><span>第 ${iterationNumber(s,r)} 次${r.reference?' · 个人参考':''}</span>${rows.length>2?`<label class="sr-only" for="compare-${i}">选择第${i+1}份记录</label><select id="compare-${i}">${rows.map(v=>`<option value="${e(v.id)}" ${v.id===r.id?'selected':''} ${v.id===pair[1-i].id?'disabled':''}>${e(caption(v))}</option>`).join('')}</select>`:''}</div>`).join('')}</div>${[...ITERATION_FIELDS,['method','方法心得']].map(([key,title])=>`<section class="r-compare-field"><h3>${title}</h3><div class="r-compare-values">${pair.map(r=>`<div>${e(r[key]||'未填写')}</div>`).join('')}</div></section>`).join('')}</div>`,{wide:true});
   for(let i=0;i<2;i++){const select=document.querySelector('#compare-'+i);if(select)select.onchange=()=>{selected[i]=select.value;draw();};}
  }draw();
 }

 return {compare,editNode,resumeNode:d=>editNode(d.payload.original?.id??null,{resume:d}),actions:{'iteration-branch':branch=>{const ui=getUI(),prior=ui.iterationBranch??'time';if(prior===branch)return;ui.iterationModes??={};ui.iterationModes[prior]={iterationParent:ui.iterationParent??null,iterationQuery:ui.iterationQuery??'',iterationDate:ui.iterationDate??'',iterationArchived:!!ui.iterationArchived};Object.assign(ui,{iterationBranch:branch,iterationParent:null,iterationQuery:'',iterationDate:'',iterationArchived:false},ui.iterationModes[branch]??{});render();requestAnimationFrame(()=>document.querySelector(`[data-action=iteration-branch][data-id=${branch}]`)?.focus({preventScroll:true}));},'new-iteration-node':()=>editNode(),'edit-iteration-node':id=>editNode(id),'iteration-project':id=>{getUI().iterationParent=id;getUI().iterationQuery='';getUI().iterationDate='';render();},'iteration-up':()=>{getUI().iterationParent=getState().iterationNodes.find(n=>n.id===getUI().iterationParent)?.parentId??null;getUI().iterationDate='';render();},'toggle-iteration-archive':()=>{getUI().iterationArchived=!getUI().iterationArchived;getUI().iterationParent=null;render();},'new-iteration-entry':id=>editEntry(id),'edit-iteration-entry':id=>editEntry(null,id)}};
}
